"use strict";(self.webpackChunkoip_docs=self.webpackChunkoip_docs||[]).push([[6478],{7644(e){e.exports=JSON.parse('{"version":{"pluginId":"reference","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"manual":[{"type":"category","label":"Getting started","items":[{"type":"link","href":"/eric-platform/reference/getting-started/","label":"From zero to a live screen","docId":"getting-started/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/install-windows/","label":"Install on Windows","docId":"install-windows/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Platform","items":[{"type":"link","href":"/eric-platform/reference/platform/","label":"The gateway","docId":"platform/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/event-streams/","label":"Event streams","docId":"event-streams/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/project-settings/","label":"Project settings","docId":"project-settings/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/script-builder/","label":"Script builder","docId":"script-builder/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/devices/","label":"Device connections","docId":"devices/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/transaction-groups/","label":"Transaction groups","docId":"transaction-groups/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/alarms/","label":"Alarm notification","docId":"alarms/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/historian/","label":"History providers","docId":"historian/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/redundancy/","label":"Redundancy pair","docId":"redundancy/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/charts/","label":"Charts","docId":"charts/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/plc/","label":"PLC runtime","docId":"plc/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/plc-windows/","label":"PLC on Windows","docId":"plc-windows/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/pid/","label":"PID block","docId":"pid/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/library/","label":"Process library","docId":"library/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/logic/","label":"Logic editor","docId":"logic/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/resources/","label":"Resource split (PLC / ERIC)","docId":"resources/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/http-endpoints/","label":"HTTP endpoints","docId":"http-endpoints/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/deployment/","label":"Deployment","docId":"deployment/index","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Security","items":[{"type":"link","href":"/eric-platform/reference/security-levels/","label":"Security levels","docId":"security-levels/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/identity-providers/","label":"Identity providers","docId":"identity-providers/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/service-policies/","label":"Service policies","docId":"service-policies/index","unlisted":false},{"type":"link","href":"/eric-platform/reference/secret-store/","label":"Secrets","docId":"secret-store/index","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"alarms/index":{"id":"alarms/index","title":"Alarm notification","description":"Alarming is where you say who is on call and how an alarm reaches them. Pipelines that are already running are listed at the top.","sidebar":"manual"},"charts/index":{"id":"charts/index","title":"Charts","description":"A chart runs a sequence on the gateway. Use a chart when the work is steps and transitions. Use a script when the work is one action.","sidebar":"manual"},"deployment/index":{"id":"deployment/index","title":"Deployment","description":"Deployment lists the settings a container and a Helm install read. The page does not change the running gateway. Copy the names into the environment of the container, or copy the short Helm block into the chart values.","sidebar":"manual"},"devices/index":{"id":"devices/index","title":"Device connections","description":"Connections lists every device and whether it is connected, connecting, faulted, or disabled. Devices, on the same page, is where you add one.","sidebar":"manual"},"event-streams/index":{"id":"event-streams/index","title":"Event streams","description":"An event stream moves one kind of event through a short pipeline. Something happens (a tag changes, a message arrives, or another screen posts an event), the stream optionally filters and reshapes it, then one or more handlers do the work: write a log line, call a URL, run a named query, publish to Kafka, or hand the event to another part of the gateway.","sidebar":"manual"},"getting-started/index":{"id":"getting-started/index","title":"Getting started","description":"This path takes a new gateway to a value you can see. You do not write code. Each step names the screen you click.","sidebar":"manual"},"historian/index":{"id":"historian/index","title":"History providers","description":"Historian is where history is stored and which tags record into it. The built-in provider local is always there. You do not create it.","sidebar":"manual"},"http-endpoints/index":{"id":"http-endpoints/index","title":"HTTP endpoints","description":"HTTP Endpoints publishes a small page or API on this gateway. Each one is served at /system/webdev/gateway/ followed by the path you choose.","sidebar":"manual"},"identity-providers/index":{"id":"identity-providers/index","title":"Identity providers","description":"An identity provider lets people sign in with an account that lives somewhere else. Identity Providers registers an OpenID Connect provider or a SAML provider, maps the provider\'s groups onto gateway roles, and checks a login when something is wrong.","sidebar":"manual"},"install-windows/index":{"id":"install-windows/index","title":"Install on Windows","description":"These installers are for a PC. No compiler and no Java install are required. The gateway installer includes the admin pages, Control Canvas (HMI and the studio), eric-plc, the Structured Text block library, and the RuSTy compiler as a separate program.","sidebar":"manual"},"library/index":{"id":"library/index","title":"Process library","description":"This PLC is running on a Windows PC. Windows can\'t give the PLC truly dedicated CPU cores, memory, or interrupt-free timing, so scan timing isn\'t guaranteed and it does not behave like a real PLC. Use it for development, testing, training, and non-critical slow process control only \u2014 never for safety or fast motion. For real-time control, run the ERIC PLC on a Linux computer with a real-time kernel.","sidebar":"manual"},"logic/index":{"id":"logic/index","title":"Logic editor","description":"This PLC is running on a Windows PC. Windows can\'t give the PLC truly dedicated CPU cores, memory, or interrupt-free timing, so scan timing isn\'t guaranteed and it does not behave like a real PLC. Use it for development, testing, training, and non-critical slow process control only \u2014 never for safety or fast motion. For real-time control, run the ERIC PLC on a Linux computer with a real-time kernel.","sidebar":"manual"},"pid/index":{"id":"pid/index","title":"PID block","description":"This PLC is running on a Windows PC. Windows can\'t give the PLC truly dedicated CPU cores, memory, or interrupt-free timing, so scan timing isn\'t guaranteed and it does not behave like a real PLC. Use it for development, testing, training, and non-critical slow process control only \u2014 never for safety or fast motion. For real-time control, run the ERIC PLC on a Linux computer with a real-time kernel.","sidebar":"manual"},"platform/index":{"id":"platform/index","title":"The gateway","description":"The gateway is the service that holds tags, projects, history, alarms, and the screens people use. One gateway serves the admin pages, Control Canvas, and the live HMI.","sidebar":"manual"},"plc-windows/index":{"id":"plc-windows/index","title":"PLC on Windows","description":"This PLC is running on a Windows PC. Windows can\'t give the PLC truly dedicated CPU cores, memory, or interrupt-free timing, so scan timing isn\'t guaranteed and it does not behave like a real PLC. Use it for development, testing, training, and non-critical slow process control only \u2014 never for safety or fast motion. For real-time control, run the ERIC PLC on a Linux computer with a real-time kernel.","sidebar":"manual"},"plc/index":{"id":"plc/index","title":"PLC runtime (preview)","description":"This PLC is running on a Windows PC. Windows can\'t give the PLC truly dedicated CPU cores, memory, or interrupt-free timing, so scan timing isn\'t guaranteed and it does not behave like a real PLC. Use it for development, testing, training, and non-critical slow process control only \u2014 never for safety or fast motion. For real-time control, run the ERIC PLC on a Linux computer with a real-time kernel.","sidebar":"manual"},"project-settings/index":{"id":"project-settings/index","title":"Project settings","description":"Project settings are in Control Canvas, in the Project panel. They apply to sessions of this project.","sidebar":"manual"},"redundancy/index":{"id":"redundancy/index","title":"Redundancy pair","description":"Network holds the pair settings for this gateway. A pair is two nodes. One is the master. The other is the backup. An independent node runs alone.","sidebar":"manual"},"resources/index":{"id":"resources/index","title":"Resource split (PLC / ERIC)","description":"This PLC is running on a Windows PC. Windows can\'t give the PLC truly dedicated CPU cores, memory, or interrupt-free timing, so scan timing isn\'t guaranteed and it does not behave like a real PLC. Use it for development, testing, training, and non-critical slow process control only \u2014 never for safety or fast motion. For real-time control, run the ERIC PLC on a Linux computer with a real-time kernel. On Windows the split is affinity, a locked working set, and the gateway -Xmx. Windows cannot fully isolate a core, and a reboot is not what applies it.","sidebar":"manual"},"script-builder/index":{"id":"script-builder/index","title":"Script builder","description":"The script builder writes a common event script so you do not have to type it. It sits under a component event\'s script in Control Canvas.","sidebar":"manual"},"secret-store/index":{"id":"secret-store/index","title":"Secrets","description":"A secret is a value the gateway stores encrypted. A database password, a token, or a key belongs here. Other settings store the reference, secret:// followed by the name, and the gateway fills in the value when it connects.","sidebar":"manual"},"security-levels/index":{"id":"security-levels/index","title":"Security levels","description":"A security level is a name a person holds after they sign in. Views and actions can require a level. Security Levels is where you build the tree, the rules that grant levels, and the grants that put one person in a level directly.","sidebar":"manual"},"service-policies/index":{"id":"service-policies/index","title":"Service policies","description":"A service policy says what a remote gateway may do on this one. It sits on Network, under the peer network status. It is separate from a security zone: a zone matches an address, and a service policy matches a peer.","sidebar":"manual"},"transaction-groups/index":{"id":"transaction-groups/index","title":"Transaction groups","description":"A transaction group moves values between tags and a database. Databases has the form under Transaction groups.","sidebar":"manual"}}}}')}}]);